function competitorFilter(){const sources=competitorState.data?.sources||[];return `<div class="competitor-filters"><label class="competitor-search-label"><span class="sr-only">Найти товар</span><input id="competitor-search" type="search" placeholder="Найти товар или группу…" value="${esc(competitorState.search)}"></label><label><span class="sr-only">Магазин</span><select id="competitor-source"><option value="all">Все магазины</option>${sources.map(s=>`<option value="${esc(s.id)}" ${competitorState.source===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="competitor-checkbox"><input id="competitor-archived" type="checkbox" ${competitorState.archived?'checked':''}>Показать архив</label></div>`;}
function competitorLinks(){const search=competitorState.search.trim().toLocaleLowerCase(),targets=competitorTargets('product').filter(t=>[t.label,t.observation?.title,t.match_group,competitorSource(t.source_id).name].join(' ').toLocaleLowerCase().includes(search)),groups=new Map();targets.forEach(t=>{const key=t.match_group||'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t);});return `<div class="competitor-section-heading"><div><h2>Выбранные товары</h2><p>Цена упаковки, вес и подтверждённые сопоставления.</p></div><button class="button primary" data-comp-action="add" data-kind="product">+ Добавить товар</button></div>${competitorFilter()}<p class="competitor-scope-note">Сравниваем только подтверждённую группу, известный вес и одну валюту. Условные цены, опт, ошибки и устаревшие данные не участвуют в сравнении. Доставка в цену товара не включена.</p>${targets.length?[...groups].map(([group,items])=>`<section class="competitor-group"><div class="competitor-group-heading"><h3>${esc(group?competitorGroupName(group):'Без группы сравнения')}</h3><span>${items.length} ${items.length===1?'карточка':'карточек'}</span></div><div class="competitor-product-grid">${items.sort((a,b)=>Number(competitorOwn(b))-Number(competitorOwn(a))).map(competitorProductCard).join('')}</div></section>`).join(''):`<div class="competitor-empty"><span aria-hidden="true">▦</span><h3>${search?'Поиск ничего не нашёл':'Начните с нескольких важных товаров'}</h3><p>${search?'Измените запрос или выбранный магазин.':'Добавьте ссылку на нашу карточку и аналог у конкурента. После фоновой проверки здесь появятся цены и история.'}</p>${search?'':'<button class="button primary" data-comp-action="add" data-kind="product">Добавить первую карточку</button>'}</div>`}`;}
