function competitorProductId(target){try{const id=new URL(target.url).searchParams.get('product_id');return id&&/^\d+$/.test(id)?Number(id):null;}catch(_){return null;}}
function competitorRequestedWeights(value){const weights=[];const expression=/(?:^|[^\p{L}\d])(\d+(?:[.,]\d+)?)\s*(кг|kg|гр\.?|г|g)(?![\p{L}])/giu;let match;while((match=expression.exec(String(value||'')))!==null){const grams=Number(match[1].replace(',','.'))*(/^(кг|kg)$/i.test(match[2])?1000:1);if(grams>0&&grams<=1000000&&!weights.includes(grams))weights.push(grams);}return weights;}
