  if(own&&competitorOwnCatalogAuthority(target)){
    const invalid=isolated&&!validTestCatalog,url=isolated?(id?'https://test.lavka-speciy.com/index.php?route=product%2Fproduct&product_id='+id:''):(product?.url||target.url),offers=product?.offers||[],catalogState=invalid?'blocked':catalog?.state;
    return {target:{...target,label:product?.label||target.label,url,last_success:invalid?null:catalog?.last_success,queued:false,last_attempt:catalogState==='ok'||catalogState==='stale'?{state:'ok'}:{state:'error',error_code:catalog?.error_code||'catalog_sync_failed'},observation:{offers,warnings:product?.warnings||[]}},offers,provenance:isolated?'Тестовая база':'База магазина',catalog:true,catalogState,missing:!product,unmapped:isolated&&!id,catalogInvalid:invalid};
  }
