      row.above=row.comparable&&row.cells.lavka.price>row.competitorMinimum+.004;row.knownPack=grouped.some(target=>competitorMatrixEntries(target).offers.some(offer=>offer.unit==='pack'&&competitorWeight(target,offer)===grams));
      rows.push(row);
