function competitorVisibleRows(){let rows=competitorMatrixRows(),search=competitorState.search.trim().toLocaleLowerCase();if(['50','500'].includes(competitorState.matrixPack))rows=rows.filter(row=>row.grams===Number(competitorState.matrixPack));else if(competitorState.matrixPack==='minimum'){const minimum=new Map();rows.forEach(row=>{if(row.cells.lavka.eligible&&(!minimum.has(row.rowGroup)||row.grams<minimum.get(row.rowGroup)))minimum.set(row.rowGroup,row.grams);});rows=rows.filter(row=>row.grams===(minimum.get(row.rowGroup)||50));}if(search)rows=rows.filter(row=>[row.label,row.group].join(' ').toLocaleLowerCase().includes(search));if(competitorState.matrixStatus==='ready')rows=rows.filter(row=>row.comparable);if(competitorState.matrixStatus==='above')rows=rows.filter(row=>row.above);if(competitorState.matrixStatus==='gaps')rows=rows.filter(row=>!row.comparable);rows.sort(competitorState.matrixSort==='gap'?(a,b)=>Number(b.above)-Number(a.above)||a.label.localeCompare(b.label,'uk'):(a,b)=>a.label.localeCompare(b.label,'uk')||a.grams-b.grams);return rows;}
function competitorShortDate(value){const date=new Date(value||'');return Number.isNaN(date.getTime())?'Дата неизвестна':date.toLocaleString('ru-RU',{timeZone:'Europe/Kiev',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}
function competitorMatrixDetailButton(row,source,label,classes=''){return `<button class="competitor-cell-detail ${classes}" type="button" data-comp-action="matrix-detail" data-row="${esc(row.key)}" data-source="${source}" aria-label="${esc(label+' · '+competitorSource(source).name+' · '+row.label+' · '+num(row.grams,2)+' г')}">${esc(label)}</button>`;}
function competitorMatrixPrice(row,source){const cell=row.cells[source],best=cell.eligible&&row.minimum!==null&&Math.abs(cell.price-row.minimum)<.005;let content;if(cell.eligible){content=`${competitorLink(cell.target.url,competitorMoney(cell.price),'competitor-cell-price')}<span class="competitor-cell-currency">UAH${best?' · минимум среди проверенных':''}</span><span class="competitor-cell-packaging">${esc(competitorPackagingNote(cell.target,cell.offer))}</span>${source==='lavka'?competitorRawPriceNote(cell.offer):''}${competitorMatrixDetailButton(row,source,source==='lavka'?cell.provenance+' · '+competitorShortDate(cell.target.last_success):competitorShortDate(cell.target.last_success),best?'best-detail':'')}`;}else{content=cell.offer&&cell.price!==null?`${competitorLink(cell.target.url,competitorMoney(cell.price),'competitor-cell-price saved')}<span class="competitor-cell-currency">UAH · прежняя цена</span>`:'<span class="competitor-cell-dash" aria-hidden="true">—</span>';content+=competitorMatrixDetailButton(row,source,cell.reason,'status-'+cell.state);}return `<td class="competitor-matrix-price ${source==='lavka'?'own':''} ${best?'is-best':''} ${cell.eligible?'eligible':'not-comparable'}" data-source="${source}"${cell.eligible?' data-price="'+esc(cell.price.toFixed(2))+'"':''}>${content}</td>`;}
function competitorCut(row){const value=competitorState.cuts[row.key]??competitorState.cut;return value===''?null:Number(value);}
function competitorOfferPriceCents(offer,fallback){const raw=offer?.provenance?.raw_price,parts=/^(\d{1,9})(?:\.(\d{1,4}))?$/.exec(String(raw??''));return parts?Number(parts[1])*100+Number((parts[2]||'').padEnd(2,'0').slice(0,2)):Math.round(Number(fallback??offer?.price)*100);}
