function competitorDraftReason(row){if(![50,500].includes(row.grams))return 'Расчёт от 50 или 500 г';if(!row.comparable)return 'Нужны цены';if(row.grams===500&&!competitorOwnBaseOffer(row))return 'Нужна наша однозначная цена 50 г';return '';}
function competitorSelectionProduct(row){const id=competitorProductId(row.own);return id?'product:'+id:'target:'+row.own.id;}
function competitorSelectRow(row,selected){if(selected){const product=competitorSelectionProduct(row);for(const other of competitorMatrixRows())if(competitorSelectionProduct(other)===product)delete competitorState.selected[other.key];competitorState.selected[row.key]=true;}else delete competitorState.selected[row.key];}
function competitorDraftChoices(){const rows=competitorVisibleRows().filter(row=>!competitorDraftReason(row)),seen=new Set();rows.sort((a,b)=>(a.grams===500?0:1)-(b.grams===500?0:1));return rows.filter(row=>{const product=competitorSelectionProduct(row);if(seen.has(product))return false;seen.add(product);return true;});}
