function competitorDraftCell(row){const selected=Boolean(competitorState.selected[row.key]),suggestion=competitorSuggestion(row),shown=competitorState.preview&&selected&&suggestion,reason=competitorDraftReason(row),canSelect=!reason;return `<td class="competitor-draft-cell"><label class="competitor-row-select"><input type="checkbox" data-matrix-select="${esc(row.key)}" ${selected?'checked':''} ${canSelect?'':'disabled'} aria-label="Выбрать ${esc(row.label)} ${num(row.grams,2)} г для черновика"><span>${esc(reason||'В черновик')}</span></label><label class="competitor-row-cut"><span>Ниже конкурента, %</span><input type="number" min="0" max="50" step="0.1" inputmode="decimal" data-matrix-cut="${esc(row.key)}" value="${esc(competitorState.cuts[row.key]??competitorState.cut)}" ${canSelect?'':'disabled'} aria-label="Снижение в процентах для ${esc(row.label)} ${num(row.grams,2)} г"></label>${shown?`<div class="competitor-suggestion" data-price="${esc(suggestion.price.toFixed(2))}" data-base-50="${esc(suggestion.base50.toFixed(2))}"><strong>${competitorMoney(suggestion.price)} UAH</strong><span>За ${num(row.grams,0)} г${suggestion.keep?' · оставить нашу цену':' · предложение'}</span>${row.grams===500?`<span class="competitor-suggestion-base">База 50 г: ${competitorMoney(suggestion.base50)} UAH</span><span>${suggestion.baseLimited?'Ограничено нашей текущей ценой 50 г':'500 г = база 50 г × 7,5'}</span>`:`<span>${suggestion.keep?'':('−'+num(suggestion.percent,1)+'% от конкурента')}</span>`}</div>`:'<span class="competitor-draft-placeholder">'+(selected?'Нажмите «Рассчитать черновик»':'—')+'</span>'}</td>`;}
